BrandingOptions.CustomCss:
button[title="Play All"] {
    display: none !important;
}
button[title="Shuffle"] {
    display: none !important;
}

/* Replace top left icon START */
/* remove the text */
a.MuiButton-root[href="#/"] {
  font-size: 0;
}

/* Remove spacing intended for the text */
a.MuiButton-root[href="#/"] .MuiButton-startIcon {
  margin: 0;
}

/* Hide the original icon */
a.MuiButton-root[href="#/"] .MuiButton-startIcon img {
  display: none;
}

/* Add the replacement icon */
a.MuiButton-root[href="#/"] .MuiButton-startIcon::before {
  content: "";

  width: 100px;
  height: 50px;
  background: url("./banner-light.b113d4d1c6c07fcb73f0.png") center / contain no-repeat;
}
/* Replace top left icon END */

/* Narrow the login form */
#loginPage .readOnlyContent,
#loginPage form {
  max-width: 22em;
}

/* Hide "please login" text, margin is to prevent login form moving too far up */
#loginPage h1 {
  display: none;
}
#loginPage .padded-left.padded-right.padded-bottom-page {
  margin-top: 50px;
}

/* Hide "forgot" buttons */
#loginPage .raised.cancel.block.btnForgotPassword.emby-button {
  display: none;
}
